let route='home',stream=null,worker=null,playing=false,busy=false,lessonCube=null,practiceCube=null,practiceMode='guided',practiceIndex=0,freeHistory=[],lessonIndex=0,moveIndex=0,stages=[],scanned=Object.fromEntries(FACES.map(f=>[f,null])),scanFace='F',paint='F',scanError='',lessonOrigin='sample',quizPassed=false,understood=new Set(),guideMode='demo',previewMoves=[],practiceStage=0;
