$('#help').onclick=()=>modal(`<span class="kicker">YOUR FIRST CUBE CLASS</span><h2>이해하고, 직접 움직여보세요.</h2><ol><li><b>내 큐브 풀기:</b> 중심색 기준으로 6면을 촬영하고 색을 확인해요.</li><li><b>초보자 순서:</b> 꽃 → 흰 십자 → 1층 → 2층 → 노란 십자 → 노란 면 → 마지막 자리 맞추기.</li><li><b>각 수업:</b> 기준색 확인 → 목표 조각 찾기 → 보낼 자리 확인 → 시범 → 직접 적용 → 결과 확인.</li></ol><p>흰색을 아래, 노랑을 위, 초록을 앞으로 잡는 표준 배색을 기준으로 해요. 회전 방향은 <b>돌릴 면을 정면에서 바라볼 때</b>를 기준으로 합니다. 사진은 서버로 전송되지 않고 브라우저에서 색만 읽어요.</p><p>큐브 상태 모델: <a class="info-link" href="https://github.com/ldez/cubejs" target="_blank" rel="noopener">cube.js (MIT)</a>. 풀이 경로는 꽃 만들기부터 층별로 진행하는 초보자 전용 방식입니다.</p>`);
function point(f,r,c){switch(f){case'U':return[c-1,1,r-1];case'D':return[c-1,-1,1-r];case'F':return[c-1,1-r,1];case'B':return[1-c,1-r,-1];case'R':return[1,1-r,1-c];case'L':return[-1,1-r,c-1];}}
function tileTransform(f,p){let a={F:'',B:'rotateY(180deg)',R:'rotateY(90deg)',L:'rotateY(-90deg)',U:'rotateX(90deg)',D:'rotateX(-90deg)'}[f];return`translate3d(${p[0]*50}px,${-p[1]*50}px,${p[2]*50}px) ${a} translateZ(25px)`;}
function cubeHTML(str=demo.asString(),id='',mask=''){let html=`<div class="scene"><div class="cube-world" ${id?`id="${id}"`:''}>`;FACES.forEach((f,fi)=>{for(let i=0;i<9;i++){let p=point(f,Math.floor(i/3),i%3),color=COLORS[str[fi*9+i]];if(mask==='cross'&&!(f==='D'&&[1,3,4,5,7].includes(i))&&!(i===4))color='#cbd0c2';if(mask==='pieces'&&i!==4&&i!==1&&i!==0)color='#c7d1c4';html+=`<div class="sticker" data-f="${f}" data-p="${p}" style="background:${color};transform:${tileTransform(f,p)}"></div>`;}});return html+'</div></div>';}
function drawCube(el,c){if(!el)return;const world=el.closest('.scene');let orientation=el.style.transform,id=el.id;world.innerHTML=cubeHTML(c.asString(),id).match(/<div class="scene">([\s\S]*)<\/div>$/)[1];if(orientation)world.firstElementChild.style.transform=orientation;}
async function turn(c,move,id){if(busy)return false;busy=true;const el=document.getElementById(id);if(el){const axis={U:'y',D:'y',R:'x',L:'x',F:'z',B:'z'}[move[0]],idx={x:0,y:1,z:2}[axis],sign={U:1,D:-1,R:1,L:-1,F:1,B:-1}[move[0]],layer=document.createElement('div');layer.className='turn-layer';[...el.querySelectorAll('.sticker')].filter(t=>+t.dataset.p.split(',')[idx]===sign).forEach(t=>layer.append(t));el.append(layer);let angle={U:-90,D:90,R:90,L:-90,F:90,B:-90}[move[0]]*(move.includes("'")?-1:move.includes('2')?2:1);await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame);layer.style.transform=`rotate${axis.toUpperCase()}(${angle}deg)`;await new Promise(r=>setTimeout(r,id==='flow-cube'?1100:530));}c.move(move);drawCube(document.getElementById(id),c);busy=false;return true;}
