const quizzes=[{q:'꽃잎으로 모아야 하는 조각은 무엇인가요?',a:['흰색이 포함된 엣지 4개','흰 코너 4개','노란 중심 조각'],correct:0,why:'꽃잎은 두 색이 함께 움직이는 흰 엣지예요. 코너는 다음 1층 수업에서 맞춰요.'},{q:'꽃잎을 아래로 내리기 전에 무엇부터 맞추나요?',a:['흰색끼리만 모은다','엣지의 옆 색과 같은 색 중심을 나란히 맞춘다','코너부터 맞춘다'],correct:1,why:'옆 색을 중심과 맞춘 다음 반 바퀴 돌려야 흰색과 옆 색이 모두 제자리에 가요.'},{q:'흰 코너가 들어갈 자리는 어떻게 알 수 있나요?',a:['흰색이 보이는 아무 자리','가장 가까운 모서리','코너의 세 색과 같은 세 중심이 만나는 자리'],correct:2,why:'코너는 세 색이 한 몸이에요. 세 중심을 기준으로 그 조각의 집을 찾을 수 있어요.'},{q:'2층으로 넣을 엣지를 고르는 기준은?',a:['노란색이 없는 윗층 엣지','노란색이 포함된 엣지','아무 코너'],correct:0,why:'노란색이 있는 엣지는 마지막 층의 조각이에요. 2층에는 노란색이 없는 엣지를 넣어요.'},{q:'노란 십자 단계에서 먼저 맞추는 것은?',a:['모든 옆면의 색','노란 엣지의 방향','모든 코너의 자리'],correct:1,why:'방향과 위치를 분리해서 배워요. 지금은 노란 엣지가 위를 보게 만드는 단계예요.'},{q:'노란 면이 완성되면 큐브도 항상 완성인가요?',a:['그렇다','옆면 색은 상관없다','아니다. 조각의 자리가 다를 수 있다'],correct:2,why:'방향이 맞아도 위치는 다를 수 있어요. 다음 단계에서 중심색을 보고 조각 자리를 맞춰요.'},{q:'마지막 코너의 올바른 자리를 결정하는 것은?',a:['같은 색의 세 중심','노란색만 보이면 된다','코너의 크기'],correct:0,why:'코너 세 색이 주변의 세 중심과 모두 맞아야 올바른 자리예요.'},{q:'마지막 엣지 순환 동작 묶음이 끝나면?',a:['코너를 다시 맞춰야 한다','코너와 아래 두 층은 유지되고 엣지 자리만 바뀐다','중심색이 바뀐다'],correct:1,why:'조각을 잠깐 옮겼다가 되돌려, 필요한 윗층 엣지의 자리만 바꾸는 원리예요.'}];
