const EDGE_COLORS=['UR','UF','UL','UB','DR','DF','DL','DB','FR','FL','BL','BR'],CORNER_COLORS=['URF','UFL','ULB','UBR','DFR','DLF','DBL','DRB'];
function targetName(seg){if(seg?.piece==null)return seg?.target||'목표 관찰';let cs=(seg.kind==='corner'?CORNER_COLORS:EDGE_COLORS)[seg.piece];return cs.split('').map(f=>NAMES[f]).join('·')+' '+(seg.kind==='corner'?'코너':'엣지')+' 옮기기';}
function tipExplanation(seg,move){if(seg?.piece==null)return seg?.why||stages[lessonIndex].principle;const corner=seg.kind==='corner',names=corner?['위·앞·오른쪽','위·앞·왼쪽','위·뒤·왼쪽','위·뒤·오른쪽','아래·앞·오른쪽','아래·앞·왼쪽','아래·뒤·왼쪽','아래·뒤·오른쪽']:['위·오른쪽','위·앞','위·왼쪽','위·뒤','아래·오른쪽','아래·앞','아래·왼쪽','아래·뒤','앞·오른쪽','앞·왼쪽','뒤·왼쪽','뒤·오른쪽'],after=lessonCube.clone().move(move),from=(corner?lessonCube.cp:lessonCube.ep).indexOf(seg.piece),to=(corner?after.cp:after.ep).indexOf(seg.piece);return targetName(seg)+' · '+(from===to?'목표 조각은 잠시 그대로 두고, 주변에 빈자리를 준비하거나 다른 조각을 복구해요.':names[from]+' 사이에서 '+names[to]+' 사이로 이동해요. 색이 함께 움직이는 모습을 따라가보세요.');}
function coachTip(seg,move,done){let title=done?'목표 모양을 확인해요':describe(move).short,text=done?observation(lessonIndex):tipExplanation(seg,move);return '<div class="cube-coach" role="status" aria-live="polite"><span class="coach-avatar">✳</span><div><small>1타강사의 한 수 코칭'+(!done?' · '+(moveIndex+1)+'번째 수':' · 단계 완료')+'</small><b>'+(done?'✓':move)+' · '+title+'</b><p>'+text+'</p></div></div>';}
function freeTip(){let m=freeHistory.at(-1);return '<div class="cube-coach" role="status" aria-live="polite"><span class="coach-avatar">✳</span><div><small>1타강사의 관찰 코칭</small><b>'+(m?m+' · '+describe(m).short:'한 수를 돌리고, 조각의 길을 관찰해요')+'</b><p>'+(m?describe(m).detail+' 두 색이 한 몸인 엣지와 세 색이 한 몸인 코너를 따라가보세요.':'오른쪽 아래 버튼에서 R을 골라보세요. 오른쪽 층의 조각들이 함께 움직이고, 중심은 기준으로 남아요.')+'</p></div></div>';}
function targetPath(seg,move){if(seg?.piece==null||!move)return '';const corner=seg.kind==='corner',c=lessonCube,after=c.clone().move(move),names=corner?['위·앞·오른쪽','위·앞·왼쪽','위·뒤·왼쪽','위·뒤·오른쪽','아래·앞·오른쪽','아래·앞·왼쪽','아래·뒤·왼쪽','아래·뒤·오른쪽']:['위·오른쪽','위·앞','위·왼쪽','위·뒤','아래·오른쪽','아래·앞','아래·왼쪽','아래·뒤','앞·오른쪽','앞·왼쪽','뒤·왼쪽','뒤·오른쪽'],from=(corner?c.cp:c.ep).indexOf(seg.piece),to=(corner?after.cp:after.ep).indexOf(seg.piece);return '<div class="target-path"><b>◎ 표시한 조각 따라가기</b><p>지금: '+names[from]+' 사이<br>이번 수 후: '+names[to]+' 사이</p><small>'+(from===to?'이 수는 목표 조각을 옮기기 위한 빈자리 준비 또는 주변 조각 복구예요.':'같은 조각의 색은 떨어지지 않고 함께 이동해요.')+'</small></div>';}
function highlightTarget(){}
function describe(m){const f=m[0],twice=m.includes('2'),rev=m.includes("'");const direction=twice?'반 바퀴 (180°)':rev?'반시계로 90°':'시계 방향으로 90°';return{short:`${FACE_NAMES[f]}을 ${direction}`,detail:`${FACE_NAMES[f]}을 정면에서 바라본 기준이에요. ${f==='U'?'윗면을 위에서 보세요.':f==='D'?'아랫면을 아래에서 보세요.':f==='B'?'뒷면을 뒤에서 바라본다고 생각하세요.':'큐브 전체가 아닌 해당 층만 돌려요.'}`};}
function observation(i){return['흰 코너는 꽃잎이 아니에요. 노란 중심 옆 네 칸만 확인하세요. 두 색을 가진 엣지는 언제나 한 몸으로 움직여요.','아랫면 흰 십자뿐 아니라 네 옆면의 중심과 엣지 색도 일치하는지 보세요. 흰색만 모이면 아직 완성이 아니에요.','각 코너의 세 색이 세 중심과 맞는지 보세요. 중간에 십자가 흐트러져도 묶음 끝에는 복구되는 모습을 관찰하세요.','동작 전후를 비교해보세요. 아래층은 복구되고 2층의 목표 엣지만 새로 제자리를 찾게 돼요.','옆 색의 자리는 아직 보지 않아요. 지금 맞추는 것은 엣지가 향하는 방향이에요.','노란 코너가 위를 향해도 옆 색은 다를 수 있어요. ‘방향’과 ‘자리’는 서로 다른 조건이에요.','노란색뿐 아니라 각 코너의 다른 두 색도 중심과 맞는지 확인하세요.','마지막 동작이 끝나면 모든 면을 확인하세요. 필요한 조각만 바꾸기 위해 다른 조각을 옮겼다가 되돌리는 원리를 떠올려보세요.'][i];}
function allButtons(){const words={U:'위',R:'오른쪽',F:'앞',D:'아래',L:'왼쪽',B:'뒤'};return ['',"'",'2'].map(suffix=>FACES.map(f=>'<button data-turn="'+f+suffix+'" aria-label="'+FACE_NAMES[f]+' '+(suffix==="'"?'반시계 방향':suffix==='2'?'반 바퀴':'시계 방향')+'"><span class="plain-turn">'+words[f]+' '+(suffix==="'"?'↶':suffix==='2'?'½':'↷')+'</span><small class="turn-notation">'+f+suffix+'</small></button>').join('')).join('');}
function practicePage(){if(!practiceCube)practiceCube=new Cube();return`${heading('LEARN BY DOING','손으로 움직이면, 원리가 보여요','한 면의 회전이 다른 면의 조각까지 어떻게 옮기는지 자유롭게 관찰해요.')}<div class="two-col"><section class="panel"><div class="stage-top"><span class="stat-pill">자유 실험실</span><span class="muted" style="font-size:10px">${freeHistory.length}번의 관찰</span></div><div class="lesson-stage with-coach">${freeTip()}${cubeHTML(practiceCube.asString(),'practice-cube')}<div class="view-controls"><button data-view="front">앞</button><button data-view="top">위</button><button data-view="bottom">아래</button><button data-view="back">뒤</button></div><span class="stage-caption">면을 돌리고, 되돌리며 변화를 관찰하세요.</span></div><div class="practice-controls">${allButtons()}</div><div class="button-row"><button class="secondary" id="undo">↶ 한 수 되돌리기</button><button class="secondary" id="reset">완성 상태로</button><button class="secondary" id="scramble">섞어보기</button></div></section><section class="panel"><span class="kicker">TODAY'S EXPERIMENT</span><h2>돌렸다가 되돌리면?</h2><p class="muted">R → U → U′ → R′ 순서로 돌려보세요.<br>조각이 전부 원래 자리로 돌아와요.</p><div class="principle"><b>왜 원래대로 돌아올까요?</b>마지막에 했던 동작부터 반대로 되돌렸기 때문이에요. 순서가 중요해요. R → U 다음에 R′ → U′을 하면 같은 결과가 나오지 않아요.</div><h3>조각이 움직이는 길을 따라가요</h3><p class="muted">흰·초록 엣지를 하나 정해보세요. 한 수를 돌릴 때마다 두 색이 함께 어디로 이동하는지 관찰해보세요. 면의 중심은 그대로 남아요.</p><div class="move-list">${freeHistory.slice(-18).map(m=>`<span class="move-chip">${m}</span>`).join('')||'<span class="muted">아직 돌린 수가 없어요.</span>'}</div><button class="primary orange" data-action="start">꽃 만들기부터 안내받으며 연습 →</button><p class="muted" style="font-size:10px">자유 실험은 수업 진도에 영향을 주지 않아요.</p></section></div>`;}
function persistCourse(){if(!stages.length)return;try{localStorage.setItem('cube-class-course',JSON.stringify({stages,lessonIndex,moveIndex,guideMode,lessonOrigin,understood:[...understood]}));}catch{}}
function render(){if(busy)return;if(route==='scan')saveScanDraft();$('#app').innerHTML={home,scan:scanPage,learn:learnPage,practice:practicePage}[route]();bind();}
function bind(){
$$('[data-action="start"]').forEach(b=>b.onclick=()=>startSample());$$('[data-action="foundation"]').forEach(b=>b.onclick=()=>LessonFlow.openExample());
$$('[data-course]').forEach(b=>b.onclick=()=>{if(b.dataset.course==='0')LessonFlow.openExample();else if(b.dataset.course==='2')LessonFlow.openExample(1);else startSample();});
$$('[data-view]').forEach(b=>b.onclick=()=>{let el=$('#lesson-cube')||$('#practice-cube');if(el&&!busy)el.style.transform={front:'rotateX(-24deg) rotateY(-32deg)',top:'rotateX(-80deg) rotateY(0deg)',bottom:'rotateX(80deg) rotateY(0deg)',back:'rotateX(-24deg) rotateY(148deg)'}[b.dataset.view];});
highlightTarget();if(route==='scan')bindScan();if(route==='learn')LessonFlow.bind();if(route==='practice')bindPractice();
}
function bindScan(){
ScanGuide.bind(scanFace);
const restart=$('#restart-scan');if(restart)restart.onclick=()=>{stopMedia();scanned=Object.fromEntries(FACES.map(f=>[f,null]));scanFace='F';paint='F';scanError='';render();$('.scan-guide').scrollIntoView({behavior:'smooth',block:'nearest'});};
if(stream){const video=$('#camera');video.srcObject=stream;video.play().catch(()=>{});}
$$('[data-face]').forEach(b=>b.onclick=()=>{stopMedia();scanFace=b.dataset.face;paint=scanFace;scanError='';render();});
$$('[data-paint]').forEach(b=>b.onclick=()=>{paint=b.dataset.paint;$$('[data-paint]').forEach(x=>x.classList.toggle('selected',x.dataset.paint===paint));});
$$('[data-cell]').forEach(b=>b.onclick=()=>{if(!scanned[scanFace])scanned[scanFace]=Array(9).fill(scanFace);scanned[scanFace][+b.dataset.cell]=paint;b.style.background=COLORS[paint];b.setAttribute('aria-label',`${+b.dataset.cell+1}번 칸 ${NAMES[paint]}`);saveScanDraft();});
$('#rotate-face').onclick=()=>{let a=scanned[scanFace]||Array(9).fill(scanFace);scanned[scanFace]=[a[6],a[3],a[0],a[7],a[4],a[1],a[8],a[5],a[2]];stopMedia();render();};
$('#confirm-face').onclick=()=>{if(!scanned[scanFace])scanned[scanFace]=Array(9).fill(scanFace);scanned[scanFace][4]=scanFace;const order=['F','R','B','L','U','D'];let next=order.find(f=>!scanned[f]);if(next){scanFace=next;paint=next;}stopMedia();render();toast(next?'다음 면의 중심색과 방향을 확인해주세요.':'6면 등록 완료. 색을 확인한 뒤 수업을 만들어요.');};
$('#open-camera').onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw Error();stopMedia();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280}},audio:false});if(route!=='scan'){stopMedia();return;}$('#camera').srcObject=stream;await $('#camera').play();toast('중앙 점선에 한 면을 맞춰 촬영하세요.');}catch{toast('카메라를 열 수 없어요. 사진 업로드 또는 색 직접 입력을 이용해주세요.');}};
$('#capture').onclick=()=>{let video=$('#camera');if(!stream||!video.videoWidth)return toast('먼저 카메라를 켜주세요.');const c=document.createElement('canvas');c.width=video.videoWidth;c.height=video.videoHeight;const ctx=c.getContext('2d');ctx.drawImage(video,0,0);const box=$('.scan-window').getBoundingClientRect(),scale=Math.max(box.width/c.width,box.height/c.height),size=190/scale;readColors(c,size);};
$('#photo').onchange=async e=>{let file=e.target.files[0];if(!file)return;const url=URL.createObjectURL(file);try{let image=new Image();image.src=url;await image.decode();const canvas=document.createElement('canvas');let ratio=Math.min(1,1400/Math.max(image.width,image.height));canvas.width=image.width*ratio;canvas.height=image.height*ratio;canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);readColors(canvas,Math.min(canvas.width,canvas.height)*.9);}catch{toast('사진을 읽지 못했어요. JPG 또는 PNG 사진을 사용해주세요.');}finally{URL.revokeObjectURL(url);}};
$('#sample').onclick=()=>startSample();$('#analyze').onclick=()=>{if(FACES.some(f=>!scanned[f])){scanError='6면을 모두 등록해주세요. 촬영하거나 색을 직접 입력한 뒤 ‘색 확인 완료’를 누르세요.';stopMedia();render();return;}lessonOrigin='camera';analyze(FACES.map(f=>scanned[f].join('')).join(''));};
}
function classify(r,g,b){let max=Math.max(r,g,b),min=Math.min(r,g,b),delta=max-min,s=max?delta/max:0,h=0;if(s<.23&&max>90)return'D';if(!delta)return'D';if(max===r)h=((g-b)/delta+6)%6;else if(max===g)h=(b-r)/delta+2;else h=(r-g)/delta+4;h*=60;if(h<13||h>345)return'L';if(h<43)return'R';if(h<80)return'U';if(h<175)return'F';return'B';}
function readColors(canvas,size){const ctx=canvas.getContext('2d',{willReadFrequently:true}),x0=(canvas.width-size)/2,y0=(canvas.height-size)/2;let result=[];for(let r=0;r<3;r++)for(let c=0;c<3;c++){let cx=Math.round(x0+(c+.5)*size/3),cy=Math.round(y0+(r+.5)*size/3),rad=Math.max(2,Math.round(size/35)),d=ctx.getImageData(Math.max(0,cx-rad),Math.max(0,cy-rad),rad*2,rad*2).data,rr=0,g=0,b=0;for(let i=0;i<d.length;i+=4){rr+=d[i];g+=d[i+1];b+=d[i+2];}let n=d.length/4;result.push(classify(rr/n,g/n,b/n));}result[4]=scanFace;const captured=scanFace;scanned[captured]=result;scanError='';const next=['F','R','B','L','U','D'].find(f=>!scanned[f]);if(next){scanFace=next;paint=next;}else stopMedia();render();if(next){$('.scan-guide').scrollIntoView({behavior:'smooth',block:'nearest'});toast(`${NAMES[captured]} 면 저장 완료. 중심색은 임의로 ${NAMES[captured]}으로 인식됩니다. 가운데 색을 확인해주세요. 다음은 ${NAMES[next]} 면이에요.`);}else{document.querySelector('.face-preview').scrollIntoView({behavior:'smooth',block:'center'});toast(`6면 촬영 완료! 중심색은 임의로 ${NAMES[captured]}으로 인식됩니다. 가운데 색과 주변 8칸을 확인해주세요.`);}}
function bindPractice(){$$('[data-turn]').forEach(b=>b.onclick=async()=>{if(busy)return;let m=b.dataset.turn;await turn(practiceCube,m,'practice-cube');freeHistory.push(m);render();});$('#undo').onclick=async()=>{if(busy||!freeHistory.length)return;let m=freeHistory.pop();await turn(practiceCube,Cube.inverse(m),'practice-cube');render();};$('#reset').onclick=()=>{if(busy)return;practiceCube=new Cube();freeHistory=[];render();};$('#scramble').onclick=()=>{if(busy)return;practiceCube=new Cube().move(DEMO);freeHistory=[];render();toast('샘플 배치로 섞었어요. 조각의 이동을 관찰해보세요.');};}
window.addEventListener('pagehide',()=>{stopMedia();saveScanDraft();});
navigate();

